import { Card } from '@/types/statistics';
import SalariesList from '../components/salariesList/SalariesList';
import SalariesStatistics from '../components/statistics/SalariesStatistics';
import { useEffect, useMemo, useState } from 'react';
import { apiGet } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';

export default function SalariesPage() {
    const [loading, setLoading] = useState(true);
    const [attendanceRate, setAttendanceRate] = useState<number>(0);
    const [totalAbsentDays, setTotalAbsentDays] = useState<number>(0);
    const [totalLeaveDays, setTotalLeaveDays] = useState<number>(0);
    const [totalPaid, setTotalPaid] = useState<number>(0);

    useEffect(() => {
        let cancelled = false;
        const load = async () => {
            setLoading(true);
            try {
                const now = new Date();
                const month = now.getMonth() + 1;
                const year = now.getFullYear();

                // 1) Salaries: sum totals from /employee-salary-list
                const firstSalary = await apiGet({
                    endpoint: endpoints.employee.salaryList,
                    queryParams: { page: 1, pageSize: 1, month, year },
                });
                const totalSalaryRows: number = firstSalary.data.data.pagination?.total ?? 0;
                if (totalSalaryRows > 0) {
                    const resSalary = await apiGet({
                        endpoint: endpoints.employee.salaryList,
                        queryParams: { page: 1, pageSize: Math.min(totalSalaryRows, 5000), month, year },
                    });
                    const rows = resSalary.data.data.data as { total_salary?: number }[];
                    const sumPaid = rows.reduce((acc, r) => acc + (Number(r.total_salary) || 0), 0);
                    if (!cancelled) setTotalPaid(Math.round(sumPaid));
                } else if (!cancelled) {
                    setTotalPaid(0);
                }

                // 2) Attendance: aggregate monthly stats from /attendance-monthly-stats (all employees)
                const resAttendance = await apiGet({
                    endpoint: endpoints.employeeAttendance.attendance,
                    queryParams: { month, year },
                });
                const rowsAttendance = resAttendance.data.data as { summary?: { total_days: number; present: number; absent: number; leave: number } }[];
                const agg = rowsAttendance.reduce(
                    (acc, r) => {
                        acc.total += Number(r.summary?.total_days) || 0;
                        acc.present += Number(r.summary?.present) || 0;
                        acc.absent += Number(r.summary?.absent) || 0;
                        acc.leave += Number(r.summary?.leave) || 0;
                        return acc;
                    },
                    { total: 0, present: 0, absent: 0, leave: 0 },
                );

                const rate = agg.total > 0 ? Math.round(((agg.present / agg.total) * 100 + Number.EPSILON) * 1) : 0;
                if (!cancelled) {
                    setAttendanceRate(rate);
                    setTotalAbsentDays(agg.absent);
                    setTotalLeaveDays(agg.leave);
                }
            } catch {
                if (!cancelled) {
                    setAttendanceRate(0);
                    setTotalAbsentDays(0);
                    setTotalLeaveDays(0);
                    setTotalPaid(0);
                }
            } finally {
                if (!cancelled) setLoading(false);
            }
        };

        load();
        return () => {
            cancelled = true;
        };
    }, []);

    const cards: Card[] = useMemo(
        () => [
            { text: 'نسبة الحضور', num: `% ${attendanceRate}`, percent: 0 },
            { text: 'إجمالي أيام الغياب', num: totalAbsentDays, percent: 0 },
            { text: 'إجمالي الإجازات', num: totalLeaveDays, percent: 0 },
            { text: 'إجمالي المدفوع', num: totalPaid.toLocaleString('en-US'), percent: 0 },
        ],
        [attendanceRate, totalAbsentDays, totalLeaveDays, totalPaid],
    );

    return (
        <div className="w-full mt-6 mb-20">
            <SalariesStatistics cards={cards} />
            {loading ? <p className="text-sm text-[#625E74] mt-4">جاري تحديث الإحصائيات…</p> : null}
            <SalariesList />
        </div>
    );
}
